export type Recipient = Readonly<{
  name: string;
  postalAddress: string;
}>;

export type ProviderRequest = Readonly<{
  shipmentId: string;
  routeCode: string;
  parcelGrams: number;
  recipient: Recipient;
  idempotencyKey: string;
}>;

export type ShippingDependencies = Readonly<{
  repository: Readonly<{
    get: (shipmentId: string) => Promise<unknown>;
    save: (shipmentId: string, record: unknown) => Promise<void>;
  }>;
  atlas: Readonly<{
    book: (request: ProviderRequest) => Promise<unknown>;
  }>;
  beacon: Readonly<{
    reserve: (request: ProviderRequest) => Promise<unknown>;
  }>;
  logger: Readonly<{
    info: (event: Record<string, unknown>) => void;
  }>;
}>;

type Provider = "atlas" | "beacon";
type RefusalReason = "unsupported_route" | "unsupported_parcel";
type Classification =
  | "unknown_failure"
  | "invalid_provider_response"
  | "repository_failure";

type Rejection = Readonly<{
  provider: Provider;
  reason: RefusalReason;
}>;

type ShipmentFields = Readonly<{
  schemaVersion: 1;
  id: string;
  routeCode: string;
  parcelGrams: number;
}>;

type QueuedShipment = ShipmentFields & Readonly<{
  state: "queued";
}>;

type DispatchedShipment = ShipmentFields & Readonly<{
  state: "dispatched";
  provider: Provider;
  bookingId: string;
  dispatchedAtMs: number;
}>;

type DeferredShipment = ShipmentFields & Readonly<{
  state: "deferred";
  nextProvider: Provider;
  retryAtMs: number;
  rejections: readonly Rejection[];
}>;

type UnavailableShipment = ShipmentFields & Readonly<{
  state: "unavailable";
  rejections: readonly Rejection[];
}>;

type StoredShipment =
  | QueuedShipment
  | DispatchedShipment
  | DeferredShipment
  | UnavailableShipment;

export type PublicShipment =
  | Omit<QueuedShipment, "schemaVersion">
  | Omit<DispatchedShipment, "schemaVersion">
  | Omit<DeferredShipment, "schemaVersion">
  | Omit<UnavailableShipment, "schemaVersion">;

type BasicErrorBody = Readonly<{
  code: "invalid_command" | "not_found";
}>;

type AbortBody = Readonly<{
  code: "dispatch_aborted";
  shipmentId: string;
  failedAt: Provider | "repository";
  classification: Classification;
  rejections: readonly Rejection[];
}>;

export type ServiceResponse = Readonly<{
  status: number;
  body: PublicShipment | BasicErrorBody | AbortBody;
}>;

type Command =
  | Readonly<{ op: "get"; shipmentId: string }>
  | Readonly<{ op: "dispatch"; shipmentId: string; nowMs: number; recipient: Recipient }>;

type CarrierOutcome =
  | Readonly<{ kind: "confirmed"; provider: Provider; bookingId: string }>
  | Readonly<{ kind: "refused"; rejection: Rejection }>
  | Readonly<{ kind: "deferred"; provider: Provider; retryAtMs: number }>
  | Readonly<{ kind: "aborted"; failedAt: Provider; classification: Exclude<Classification, "repository_failure"> }>;

type DispatchPlan = Readonly<{
  nextProvider: Provider;
  rejections: readonly Rejection[];
}>;

type DiagnosticEvent =
  | Readonly<{ shipmentId: string; action: "dispatched"; provider: Provider }>
  | Readonly<{
      shipmentId: string;
      action: "deferred";
      provider: Provider;
      retryAtMs: number;
      rejections: readonly Rejection[];
    }>
  | Readonly<{ shipmentId: string; action: "unavailable"; rejections: readonly Rejection[] }>
  | Readonly<{
      shipmentId: string;
      action: "aborted";
      failedAt: Provider | "repository";
      classification: Classification;
      rejections: readonly Rejection[];
    }>;

function isObject(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}

function isSafeInteger(value: unknown): value is number {
  return typeof value === "number" && Number.isSafeInteger(value);
}

function isPositiveSafeInteger(value: unknown): value is number {
  return isSafeInteger(value) && value > 0;
}

function isProvider(value: unknown): value is Provider {
  return value === "atlas" || value === "beacon";
}

function isRefusalReason(value: unknown): value is RefusalReason {
  return value === "unsupported_route" || value === "unsupported_parcel";
}

function isRejection(value: unknown): value is Rejection {
  return isObject(value) && isProvider(value.provider) && isRefusalReason(value.reason);
}

function areRejections(value: unknown): value is readonly Rejection[] {
  return Array.isArray(value) && value.every(isRejection);
}

function parseCommand(value: unknown): Command | undefined {
  if (!isObject(value) || typeof value.shipmentId !== "string" || value.shipmentId.length === 0) {
    return undefined;
  }
  if (value.op === "get") {
    return { op: "get", shipmentId: value.shipmentId };
  }
  if (
    value.op !== "dispatch" ||
    !isSafeInteger(value.nowMs) ||
    value.nowMs < 0 ||
    !isObject(value.recipient) ||
    typeof value.recipient.name !== "string" ||
    value.recipient.name.trim().length === 0 ||
    typeof value.recipient.postalAddress !== "string" ||
    value.recipient.postalAddress.trim().length === 0
  ) {
    return undefined;
  }
  return {
    op: "dispatch",
    shipmentId: value.shipmentId,
    nowMs: value.nowMs,
    recipient: {
      name: value.recipient.name,
      postalAddress: value.recipient.postalAddress,
    },
  };
}

function parseStoredShipment(value: unknown): StoredShipment {
  if (
    !isObject(value) ||
    value.schemaVersion !== 1 ||
    typeof value.id !== "string" ||
    typeof value.routeCode !== "string" ||
    !isPositiveSafeInteger(value.parcelGrams)
  ) {
    throw new TypeError("Invalid stored shipment");
  }

  const base: ShipmentFields = {
    schemaVersion: 1,
    id: value.id,
    routeCode: value.routeCode,
    parcelGrams: value.parcelGrams,
  };

  if (value.state === "queued") {
    return { ...base, state: "queued" };
  }
  if (
    value.state === "dispatched" &&
    isProvider(value.provider) &&
    typeof value.bookingId === "string" &&
    value.bookingId.length > 0 &&
    isSafeInteger(value.dispatchedAtMs) &&
    value.dispatchedAtMs >= 0
  ) {
    return {
      ...base,
      state: "dispatched",
      provider: value.provider,
      bookingId: value.bookingId,
      dispatchedAtMs: value.dispatchedAtMs,
    };
  }
  if (
    value.state === "deferred" &&
    isProvider(value.nextProvider) &&
    isSafeInteger(value.retryAtMs) &&
    value.retryAtMs >= 0 &&
    areRejections(value.rejections)
  ) {
    return {
      ...base,
      state: "deferred",
      nextProvider: value.nextProvider,
      retryAtMs: value.retryAtMs,
      rejections: value.rejections.map(copyRejection),
    };
  }
  if (value.state === "unavailable" && areRejections(value.rejections)) {
    return {
      ...base,
      state: "unavailable",
      rejections: value.rejections.map(copyRejection),
    };
  }

  throw new TypeError("Invalid stored shipment");
}

function copyRejection(rejection: Rejection): Rejection {
  return {
    provider: rejection.provider,
    reason: rejection.reason,
  };
}

function copyRejections(rejections: readonly Rejection[]): readonly Rejection[] {
  return rejections.map(copyRejection);
}

function publicShipment(shipment: StoredShipment): PublicShipment {
  const fields = {
    id: shipment.id,
    routeCode: shipment.routeCode,
    parcelGrams: shipment.parcelGrams,
  };
  switch (shipment.state) {
    case "queued":
      return { ...fields, state: "queued" };
    case "dispatched":
      return {
        ...fields,
        state: "dispatched",
        provider: shipment.provider,
        bookingId: shipment.bookingId,
        dispatchedAtMs: shipment.dispatchedAtMs,
      };
    case "deferred":
      return {
        ...fields,
        state: "deferred",
        nextProvider: shipment.nextProvider,
        retryAtMs: shipment.retryAtMs,
        rejections: copyRejections(shipment.rejections),
      };
    case "unavailable":
      return {
        ...fields,
        state: "unavailable",
        rejections: copyRejections(shipment.rejections),
      };
  }
}

function buildRequest(shipment: StoredShipment, recipient: Recipient): ProviderRequest {
  return {
    shipmentId: shipment.id,
    routeCode: shipment.routeCode,
    parcelGrams: shipment.parcelGrams,
    recipient: {
      name: recipient.name,
      postalAddress: recipient.postalAddress,
    },
    idempotencyKey: shipment.id,
  };
}

function classifyAtlasRejection(error: unknown, nowMs: number): CarrierOutcome {
  if (!isObject(error) || typeof error.code !== "string") {
    return { kind: "aborted", failedAt: "atlas", classification: "unknown_failure" };
  }
  if (error.code === "cannot_ship") {
    if (!isRefusalReason(error.reason)) {
      return { kind: "aborted", failedAt: "atlas", classification: "invalid_provider_response" };
    }
    return {
      kind: "refused",
      rejection: { provider: "atlas", reason: error.reason },
    };
  }
  if (error.code === "rate_limited") {
    if (!isSafeInteger(error.retryAtMs) || error.retryAtMs <= nowMs) {
      return { kind: "aborted", failedAt: "atlas", classification: "invalid_provider_response" };
    }
    return { kind: "deferred", provider: "atlas", retryAtMs: error.retryAtMs };
  }
  return { kind: "aborted", failedAt: "atlas", classification: "unknown_failure" };
}

function classifyBeaconRejection(error: unknown, nowMs: number): CarrierOutcome {
  if (!isObject(error) || typeof error.type !== "string") {
    return { kind: "aborted", failedAt: "beacon", classification: "unknown_failure" };
  }
  if (error.type === "rejected") {
    if (!isObject(error.details) || !isRefusalReason(error.details.reason)) {
      return { kind: "aborted", failedAt: "beacon", classification: "invalid_provider_response" };
    }
    return {
      kind: "refused",
      rejection: { provider: "beacon", reason: error.details.reason },
    };
  }
  if (error.type === "throttled") {
    if (!isObject(error.details) || !isSafeInteger(error.details.retryAtMs) || error.details.retryAtMs <= nowMs) {
      return { kind: "aborted", failedAt: "beacon", classification: "invalid_provider_response" };
    }
    return { kind: "deferred", provider: "beacon", retryAtMs: error.details.retryAtMs };
  }
  return { kind: "aborted", failedAt: "beacon", classification: "unknown_failure" };
}

async function attemptCarrier(
  dependencies: ShippingDependencies,
  provider: Provider,
  request: ProviderRequest,
  nowMs: number,
): Promise<CarrierOutcome> {
  if (provider === "atlas") {
    try {
      const confirmation = await dependencies.atlas.book(request);
      if (!isObject(confirmation) || typeof confirmation.bookingId !== "string" || confirmation.bookingId.length === 0) {
        return { kind: "aborted", failedAt: "atlas", classification: "invalid_provider_response" };
      }
      return { kind: "confirmed", provider: "atlas", bookingId: confirmation.bookingId };
    } catch (error: unknown) {
      return classifyAtlasRejection(error, nowMs);
    }
  }

  try {
    const confirmation = await dependencies.beacon.reserve(request);
    if (!isObject(confirmation) || typeof confirmation.reference !== "string" || confirmation.reference.length === 0) {
      return { kind: "aborted", failedAt: "beacon", classification: "invalid_provider_response" };
    }
    return { kind: "confirmed", provider: "beacon", bookingId: confirmation.reference };
  } catch (error: unknown) {
    return classifyBeaconRejection(error, nowMs);
  }
}

function abortResponse(
  shipmentId: string,
  failedAt: Provider | "repository",
  classification: Classification,
  rejections: readonly Rejection[],
): ServiceResponse {
  return {
    status: 500,
    body: {
      code: "dispatch_aborted",
      shipmentId,
      failedAt,
      classification,
      rejections: copyRejections(rejections),
    },
  };
}

function emitAbort(
  dependencies: ShippingDependencies,
  shipmentId: string,
  failedAt: Provider | "repository",
  classification: Classification,
  rejections: readonly Rejection[],
): void {
  emit(dependencies, {
    shipmentId,
    action: "aborted",
    failedAt,
    classification,
    rejections: copyRejections(rejections),
  });
}

function emit(dependencies: ShippingDependencies, event: DiagnosticEvent): void {
  dependencies.logger.info(event);
}

async function saveDecision(
  dependencies: ShippingDependencies,
  shipment: StoredShipment,
  decision: StoredShipment,
  status: number,
  event: DiagnosticEvent,
  abortRejections: readonly Rejection[],
): Promise<ServiceResponse> {
  try {
    await dependencies.repository.save(shipment.id, decision);
  } catch {
    emitAbort(dependencies, shipment.id, "repository", "repository_failure", abortRejections);
    return abortResponse(shipment.id, "repository", "repository_failure", abortRejections);
  }
  emit(dependencies, event);
  return { status, body: publicShipment(decision) };
}

function makeDispatched(
  shipment: StoredShipment,
  provider: Provider,
  bookingId: string,
  nowMs: number,
): DispatchedShipment {
  return {
    schemaVersion: 1,
    id: shipment.id,
    routeCode: shipment.routeCode,
    parcelGrams: shipment.parcelGrams,
    state: "dispatched",
    provider,
    bookingId,
    dispatchedAtMs: nowMs,
  };
}

function makeDeferred(
  shipment: StoredShipment,
  nextProvider: Provider,
  retryAtMs: number,
  rejections: readonly Rejection[],
): DeferredShipment {
  return {
    schemaVersion: 1,
    id: shipment.id,
    routeCode: shipment.routeCode,
    parcelGrams: shipment.parcelGrams,
    state: "deferred",
    nextProvider,
    retryAtMs,
    rejections: copyRejections(rejections),
  };
}

function makeUnavailable(
  shipment: StoredShipment,
  rejections: readonly Rejection[],
): UnavailableShipment {
  return {
    schemaVersion: 1,
    id: shipment.id,
    routeCode: shipment.routeCode,
    parcelGrams: shipment.parcelGrams,
    state: "unavailable",
    rejections: copyRejections(rejections),
  };
}

async function handleDispatch(
  dependencies: ShippingDependencies,
  command: Extract<Command, { op: "dispatch" }>,
  shipment: StoredShipment,
): Promise<ServiceResponse> {
  if (shipment.state === "dispatched") {
    return { status: 200, body: publicShipment(shipment) };
  }
  if (shipment.state === "unavailable") {
    return { status: 422, body: publicShipment(shipment) };
  }
  if (shipment.state === "deferred" && command.nowMs < shipment.retryAtMs) {
    return { status: 202, body: publicShipment(shipment) };
  }

  const plan: DispatchPlan = shipment.state === "deferred"
    ? { nextProvider: shipment.nextProvider, rejections: copyRejections(shipment.rejections) }
    : { nextProvider: "atlas", rejections: [] };

  return runPlan(dependencies, command, shipment, plan);
}

async function runPlan(
  dependencies: ShippingDependencies,
  command: Extract<Command, { op: "dispatch" }>,
  shipment: StoredShipment,
  plan: DispatchPlan,
): Promise<ServiceResponse> {
  const request = buildRequest(shipment, command.recipient);
  const outcome = await attemptCarrier(dependencies, plan.nextProvider, request, command.nowMs);

  switch (outcome.kind) {
    case "confirmed": {
      const dispatched = makeDispatched(shipment, outcome.provider, outcome.bookingId, command.nowMs);
      return saveDecision(
        dependencies,
        shipment,
        dispatched,
        200,
        { shipmentId: shipment.id, action: "dispatched", provider: outcome.provider },
        plan.rejections,
      );
    }
    case "deferred": {
      const deferred = makeDeferred(shipment, outcome.provider, outcome.retryAtMs, plan.rejections);
      return saveDecision(
        dependencies,
        shipment,
        deferred,
        202,
        {
          shipmentId: shipment.id,
          action: "deferred",
          provider: outcome.provider,
          retryAtMs: outcome.retryAtMs,
          rejections: copyRejections(plan.rejections),
        },
        plan.rejections,
      );
    }
    case "aborted":
      emitAbort(dependencies, shipment.id, outcome.failedAt, outcome.classification, plan.rejections);
      return abortResponse(shipment.id, outcome.failedAt, outcome.classification, plan.rejections);
    case "refused":
      return handleRefusal(dependencies, command, shipment, plan, outcome.rejection);
  }
}

async function handleRefusal(
  dependencies: ShippingDependencies,
  command: Extract<Command, { op: "dispatch" }>,
  shipment: StoredShipment,
  plan: DispatchPlan,
  rejection: Rejection,
): Promise<ServiceResponse> {
  const rejections = [...plan.rejections, rejection];
  if (rejection.provider === "atlas") {
    return runPlan(dependencies, command, shipment, {
      nextProvider: "beacon",
      rejections,
    });
  }

  const unavailable = makeUnavailable(shipment, rejections);
  return saveDecision(
    dependencies,
    shipment,
    unavailable,
    422,
    { shipmentId: shipment.id, action: "unavailable", rejections: copyRejections(rejections) },
    rejections,
  );
}

export function createShippingService(dependencies: ShippingDependencies) {
  async function handle(input: unknown): Promise<ServiceResponse> {
    const command = parseCommand(input);
    if (!command) {
      return { status: 400, body: { code: "invalid_command" } };
    }

    let value: unknown;
    try {
      value = await dependencies.repository.get(command.shipmentId);
    } catch {
      emitAbort(dependencies, command.shipmentId, "repository", "repository_failure", []);
      return abortResponse(command.shipmentId, "repository", "repository_failure", []);
    }
    if (value === undefined) {
      return { status: 404, body: { code: "not_found" } };
    }

    const shipment = parseStoredShipment(value);
    if (command.op === "get") {
      return { status: 200, body: publicShipment(shipment) };
    }

    return handleDispatch(dependencies, command, shipment);
  }

  return { handle };
}
